Claro! Aqui está um exemplo completo de como criar um bot do Telegram com Node.js e Telegraf que recebe um intervalo em horas/minutos (no formato HH:MM), realiza uma contagem regressiva e envia notificações a cada 30 minutos.

## ✅ Pré-requisitos

Crie um novo projeto Node.js:

```bash
mkdir contador-telegram-bot
cd contador-telegram-bot
npm init -y
npm install telegraf node-cron @babel/node dotenv
```

Adicione as variáveis de ambiente no arquivo `.env`:

```env
# Crie seu token do bot no @BotFather no Telegram
TELEGRAM_BOT_TOKEN=SEU_TOKEN_AQUI

# Seu número de telefone (opcional para verificação via API)
TELEGRAM_PHONE_NUMBER=SEU_NUMERO_DE_TELEFONO
```

## 📁 Estrutura do Projeto

Organize o código desta forma:

```
contador-telegram-bot/
├── .env
├── index.js
└── package.json
```

### 🧠 index.js

Aqui está a lógica completa do bot com contagem regressiva:

```javascript
require('dotenv').config();
const { Telegraf } = require('telegraf');
const cron = require('node-cron');

// Configuração da API Token do Bot do Telegram
const token = process.env.TELEGRAM_BOT_TOKEN || 'YOUR_BOT_TOKEN'; // Substitua pelo seu token
const bot = new Telegraf(token);

// Variável temporária para armazenar o tempo configurado pelo usuário
let countDownTime = null;

// Função para contar quanto falta até o tempo total
function getRemainingTime(secondsLeft) {
  if (!secondsLeft) return "🎯 Tempo decorrido";

  const hrs = Math.floor(secondsLeft / 3600);
  const min = Math.floor((secondsLeft % 3600) / 60);
  const sec = secondsLeft % 60;

  let msg = "";

  if (hrs > 0) msg += `${hrs}h `;
  msg += `${min}m `;
  msg += `${sec}s`;

  return `⏰ Faltam: ${msg}`;
}

// Comandos do bot
bot.start(({ ctx }) => {
  ctx.reply("Olá! 👋\n\nUse os comandos abaixo:\n\n/timer [HH:MM] - Iniciar contador", { reply_markup: { inline_keyboard: [] } });
});

bot.command("timer", async ({ ctx }) => {
  const inputText = ctx.args.join(" ");
  const parts = inputText.split(":");

  if (parts.length !== 2) {
    return ctx.reply("❌ Formato inválido. Use HH:MM (ex: 01:30)", { html: true });
  }

  const hours = parseInt(parts[0]);
  const minutes = parseInt(parts[1]);

  if (isNaN(hours) || isNaN(minutes)) {
    return ctx.reply("❌ Digite apenas números (ex: 02:15).", { html: true });
  }

  if (hours < 0 || hours > 24 || minutes < 0 || minutes > 59) {
    return ctx.reply("❌ Valores inválidos (HH:00 a 24:59).", { html: true });
  }

  // Parar se já houver um timer em andamento
  if (countDownTime) {
    stopTimer(countDownTime);
    countDownTime = null;
  }

  // Calcular tempo total
  const totalSeconds = ((hours * 60) + minutes) * 60;

  // Inicializar timer
  startTimer(totalSeconds);

  await ctx.reply(`✅ Temporizador iniciado!\n\nTotal estimado: ${formatTimeDisplay(hours, minutes)}\n\nSó mais ${minutes === 0 && hours === 0 ? "tempo" : formatTimeDisplay(hours, minutes)}...`, {
    html: true
  });
});

// Comandos para parar/reiniciar
bot.command("stop", async ({ ctx }) => {
  if (countDownTime) {
    stopTimer(countDownTime);
    await ctx.reply("✅ Temporizador parado.");
  } else {
    await ctx.reply("⛔ Não há timer ativo.");
  }
});

bot.command("reset", async ({ ctx }) => {
  if (countDownTime) {
    stopTimer(countDownTime);
  }
  countDownTime = null;
  await ctx.reply("🔄 Resetado! O timer agora não está rodando.", {
    html: true
  });
});

// Funções internas de timer
function startTimer(totalSeconds) {
  countDownTime = Date.now() + totalSeconds;

  // Enviar alerta inicial de 30 minutos
  sendNotification(30 * 60);
  console.log("⏳ Timer iniciado:", countDownTime);
}

function stopTimer(timerDate) {
  if (timerDate) clearTimeout(timerDate);
  countDownTime = null;
  console.log("⏸️ Timer encerrado.");
}

async function sendNotification(secondsLeft) {
  const remaining = (Math.ceil(secondsLeft / 30));
  if (remaining >= 1 && countDownTime === null) {
    await ctx.reply(`⏰ Alerta de ${getRemainingTime(Math.max(0, remaining))}`, {
      html: true,
      parse_mode: 'HTML'
    });
  }
}

// Cron Job principal
setInterval(async () => {
  if (countDownTime === null) return;

  const now = Date.now();
  const timeLeft = Math.max(0, countDownTime - now);

  const isHalfHour = Math.floor(timeLeft / 30) <= 1;

  if (timeLeft <= 300 && isHalfHour) {
    await sendNotification(timeLeft);
  }

  if (timeLeft <= 0) {
    stopTimer(countDownTime);
    await ctx.reply("⏱️ ¡Temporizador acabou! 🎉", {
      html: true,
      parse_mode: 'HTML'
    });
  }
}, 1000);

// Polishing de resposta
function formatTimeDisplay(hours, minutes) {
  const h = String(hours).padStart(2, '0');
  const m = String(minutes).padStart(2, '0');
  return `${h}:${m}`;
}

// Iniciar o bot
bot.launch().catch(err => console.error('Erro ao iniciar o bot:', err));
```

## 🧪 Instruções de Uso

1. **Obtenha um token** do bot usando o comando `/newbot` no [@BotFather](https://t.me/BotFather).
2. **Configure o arquivo `.env`**, substituindo `"SEU_TOKEN_AQUI"` pelo seu token real.
3. **Inicie o servidor com**:
   ```bash
   node index.js
   ```
4. **Envie o link do bot para o Telegram**, ou abra direto o URL gerado e use os seguintes comandos:

| Comando | Descrição                     |
|---------|-------------------------------|
| `/timer` | Inicia timer: `02:30`         |
| `/stop`  | Para timer atual              |
| `/reset` | Reseta timer sem sair do chat |

## ⚙️ Recursos Adicionais Sugeridos

- **Persistência**: Adicionar localStorage para salvar timers entre reinícios
- **Mensagens personalizadas**: Definir mensagem individual por horário (ex: manhã, noite)
- **Gráficos visuais**: Usar imagem baseada no tempo restante com canvas
- **Multilíngue**: Suporte de localização (por ex: en_US, pt_BR)

## ⚠️ Notas Importantes

- O bot usa `node-cron`, certifique-se de tê-lo instalado (`npm install node-cron`)
- Se usar Webhook, configure CORS na API para evitar erros
- Para produção, adicione proteção contra loops infinitos de timer
- Considere adicionar log de debug para facilitar depuração

Se precisar de qualquer ajuste ou funcionalidade adicional, estou à disposição para ajudar! 😊

