                            <h3 class="text-white font-semibold">Próximos Prazos e Compromissos</h3>
                            ${appState.agenda.filter(e => e.urgency === 'Urgente' && !e.completed).length > 0 ? 
                                '<span class="text-xs bg-red-500/20 text-red-400 px-2 py-1 rounded animate-pulse">ATENÇÃO: URGENTE</span>' : ''}
                        </div>

                        <div class="space-y-3" id="agenda-list-container">
                            ${appState.agenda.map(ev => `
                                <div class="bg-dark-card p-4 rounded-lg border border-dark-border flex items-start gap-4">
                                    <div class="mt-1 p-2 rounded bg-slate-700 text-white text-xs min-w-[60px] text-center">
                                        <div>${new Date(ev.date).getDate()}</div>
                                        <div class="text-[10px] text-slate-400">${new Date(ev.date).toLocaleString('pt-BR', {month:'short'})}</div>
                                    </div>
                                    <div class="flex-1">
                                        <div class="flex justify-between">
                                            <h4 class="text-slate-200 font-medium text-sm">${ev.desc}</h4>
