                                        </div>
                                        <p class="text-xs text-slate-400 mt-1">${ev.notes || 'Sem observações'}</p>
                                    </div>
                                    <div class="flex flex-col gap-2 mt-2">
                                        <button onclick="completeTask('${ev.id}')"< class="text-xs text-brand-500 hover:text-brand-400 border border-brand-500/30 px-3 py-1 rounded hover:bg-brand-500/10 transition">Concluir</button>
