                            `).join('')}
                        </div>
                    </div>
                 </div>
            `;
        }

        // 5. FINANÇAS
        function renderFinance(container) {
            container.innerHTML = `
                <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <div class="lg:col-span-2 space-y-4">
                        <h3 class="text-white font-semibold">Histórico Transacional</h3>
                        <div class="bg-dark-card border border-dark-border rounded-xl overflow-hidden">
                            <table class="w-full text-left text-sm text-slate-400">
                                <thead class="bg-dark-card text-xs uppercase text-slate-500">
                                    <tr><th class="px-4 py-3">Descrição</th><th class="px-4 py-3">Data</th><th class="px-4 py-3">Categoria</th><th class="px-4 py-3 text-right">Valor</th></tr>
