                </div>
            `;
            renderFinanceTable();
            calculateBalance();
        }

        function renderFinanceTable() {
            $('#fin-table').html(appState.finance.map(f => `
                <tr class="hover:bg-white/5">
                    <td class="px-4 py-3 text-white font-medium">${f.desc}</td>
                    <td class="px-4 py-3 text-slate-500">${new Date(f.date).toLocaleDateString('pt-BR')}</td>
                    <td class="px-4 py-3">
                        ${f.type === 'Entrada' ? '<span class="text-green-400 text-xs bg-green-500/10 px-2 py-1 rounded">Entrada</span>' : '<span class="text-red-400 text-xs bg-red-500/10 px-2 py-1 rounded">Saída</span>'}
