                        </div>
                    </div>
                    <div class="space-y-3" id="tasks-list">
                        ${appState.tasks.map(task => `
                            <label class="flex items-center gap-4 bg-slate-800 p-4 rounded-lg border border-slate-700 hover:bg-slate-700 transition cursor-pointer">
                                <input type="checkbox" class="task-checkbox" ${task.completed ? 'checked' : ''} onchange="toggleTask('${task.id}', this.checked)">
                                <span class="${task.completed ? 'line-through text-slate-500' : 'text-white'} flex-1">${task.desc}</span>
                                <button onclick="delTask('${task.id}')" class="opacity-0 hover:opacity-100 text-red-400"><i class="fa-solid fa-trash"></i></button>
                            </label>
                        `).join('')}
                        ${appState.tasks.length === 0 ? '<p class="text-slate-500 italic">Sem tarefas.</p>' : ''}
                    </div>
                </div>
            `;
        }

        // --- AGENDA INTERATIVA ---
        function addAgendaItem() {
            const desc = prompt("Descreva o compromisso ou prazo:");
            if(desc) {
                const urgency = prompt("Prioridade? (Urgente, Normal):", "Normal").toLowerCase();
                const date = prompt("Data: (dd/mm/yyyy):", new Date().toISOString().slice(0, 10));

                appState.agenda.push({
                    id: Date.now(),
                    desc: desc,
                    urgency: urgency,
                    notes: "",
                    date: date,
                    completed: false
                });
                saveToLocal();
                renderAgenda($('#content-area'));
            }
        }

        function completeTask(id) {
            const ev = appState.agenda.find(x => x.id == id);
            if(ev) {
                ev.completed = true;
                saveToLocal();
                showToast('Compromisso marcado como concluído');
                renderAgenda($('#content-area'));
            }
        }

        // --- SISTEMA DE INICIALIZAÇÃO ---
        window.onload = function() {
            if(localStorage.getItem('missy_state')) {
                loadFromLocal();
            } else {
                // Seed inicial vazia para evitar erros
                appState = { ...appState };
                saveToLocal();
            }
            initSidebar();
            showToast("Sistema Missy carregado com sucesso.");
        };

        function toggleMobileMenu() {
            alert("Menu Mobile simplificado para este demonstrativo único.");
        }
    </script>
</body>
</html>
