                    </button>
                    <!-- Dropdown Mockup -->
                    <div class="absolute right-0 mt-2 w-48 bg-dark-card border border-dark-border rounded-lg shadow-xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all transform translate-y-[-10px]">
                        <div class="py-1">
                            <a href="#" class="block px-4 py-2 text-sm hover:bg-dark-border hover:text-white">Perfil</a>
                            <a href="#" class="block px-4 py-2 text-sm hover:bg-dark-border hover:text-white">Sair</a>
