            </div>
        </header>

        <!-- DYNAMIC PAGE CONTENT -->
        <div id="content-area" class="flex-1 overflow-y-auto p-6 relative scroll-smooth">
            <!-- Conteúdo injetado via JS -->
        </div>

    </main>

    <!-- MODAL GENERIC STRUCTURE -->
    <div id="modal-overlay" onclick="closeModal(event)" class="fixed inset-0 bg-black/70 z-50 flex items-center justify-center backdrop-blur-sm">
        <div id="modal-box" class="bg-dark-card w-full max-w-2xl max-h-[90vh] overflow-y-auto modal-content rounded-xl border border-dark-border shadow-2xl p-6 relative">
            <button onclick="closeModal()" class="absolute top-4 right-4 text-slate-400 hover:text-white text-xl"><i class="fa-solid fa-xmark"></i></button>

            <!-- Conteúdo do Modal injetado dinamicamente -->
        </div>
    </div>

    <!-- JAVASCRIPT LOGIC -->
    <script>
        /**
         * MISSY CORE SYSTEM
         * Arquitetura baseada em objetos e estado global
         */

        const dbKeys = {
            clients: 'missy_clients',
            processes: 'missy_processes',
            documents: 'missy_documents',
            agenda: 'missy_agenda',
            finance: 'missy_finance',
            tasks: 'missy_tasks',
            colleagues: 'missy_colleagues',
            intimations: 'missy_intimations'
        };

        // Estado Inicial (Default)
        let appState = {
            currentView: 'dashboard',
            theme: 'dark',
            clients: [],
            processes: [],
            documents: [],
            agenda: [],
            finance: [],
            tasks: [],
            colleagues: []
        };

        // --- UTILITÁRIOS DE DOM E STORAGE ---

        const $ = (sel) => document.querySelector(sel);
        const $$ = (sel) => document.querySelectorAll(sel);

        const saveToLocal = () => {
            localStorage.setItem('missy_state', JSON.stringify(appState));
            localStorage.setItem('missy_theme', appState.theme);
        };

        const loadFromLocal = () => {
            const state = localStorage.getItem('missy_state');
            if (state) appState = JSON.parse(state);

            const savedTheme = localStorage.getItem('missy_theme');
            if (savedTheme === 'light') document.documentElement.classList.remove('dark');
            else document.documentElement.classList.add('dark');

            applyTheme();
        };

        const showToast = (message, type = 'success') => {
            const container = $('#toast-container');
            const el = document.createElement('div');
            el.className = `transform transition-all duration-300 translate-y-0 opacity-100 ${type === 'error' ? 'border-l-4 border-red-500' : 'border-l-4 border-brand-500'} bg-dark-card border-l p-4 rounded shadow-lg flex items-center gap-3`;

            const icon = type === 'error' ? '<i class="fa-solid fa-circle-exclamation text-red-400"></i>' : '<i class="fa-solid fa-check-circle text-brand-500"></i>';

            el.innerHTML = `
                <div>${icon}</div>
                <span class="text-sm font-medium text-slate-200">${message}</span>
            `;

            container.prepend(el);
            setTimeout(() => {
                el.classList.add('translate-y-2', 'opacity-0');
                setTimeout(() => el.remove(), 300);
            }, 3000);
        };

        // --- NAVEGAÇÃO E INTERFACE ---

        function initSidebar() {
            const menu = $('#sidebar-menu');
            const views = ['dashboard', 'clientes', 'processos', 'documentos', 'agenda', 'finance', 'tarefas', 'colaboradores', 'intimações', 'backup', 'config'];

            views.forEach(view => {
                const item = document.createElement('a');
                item.href = `#${view}`;
                item.id = `nav-${view}`;
                item.className = `flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-colors group ${appState.currentView === view ? 'bg-brand-500/20 text-brand-500' : 'text-slate-400 hover:bg-dark-border hover:text-white'}`;

                // Ícones
                let iconClass = '';
                switch(view) {
                    case 'dashboard': iconClass = 'fa-solid fa-gauge-high'; break;
                    case 'clientes': iconClass = 'fa-solid fa-address-book'; break;
                    case 'processos': iconClass = 'fa-solid fa-scale-balanced'; break;
                    case 'documentos': iconClass = 'fa-solid fa-file-lines'; break;
                    case 'agenda': iconClass = 'fa-calendar-days'; break;
                    case 'finance': iconClass = 'fa-solid fa-money-bill-wave'; break;
                    case 'tarefas': iconClass = 'fa-solid fa-list-check'; break;
                    case 'colaboradores': iconClass = 'fa-solid fa-users'; break;
                    case 'intimações': iconClass = 'fa-bullhorn'; break;
                    case 'backup': iconClass = 'fa-solid fa-download'; break;
                    case 'config': iconClass = 'fa-solid fa-sliders'; break;
                }

                item.innerHTML = `<i class="fa-solid ${iconClass} w-5 text-center"></i> ${view.charAt(0).toUpperCase() + view.slice(1)}`;

                item.onclick = () => navigateTo(view);
                menu.appendChild(item);
            });
        }

        function navigateTo(view) {
            appState.currentView = view;

            // Atualizar estilo ativo do menu
            $$('#sidebar-menu a').forEach(a => {
                a.className = `flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-colors ${a.id === `nav-${view}` ? 'bg-brand-500/20 text-brand-500' : 'text-slate-400 hover:bg-dark-border hover:text-white'}`;
            });

            // Title do header
            const titles = { dashboard: 'Visão Geral', clientes: 'Gestão de Clientes', processos: 'Processos e Causas', documentos: 'Documentação', agenda: 'Agenda e Prazos', finance: 'Finanças', tarefas: 'Tarefas diárias', colaboradores: 'Colaboração', intimações: 'Intimações & Alerts', backup: 'Segurança e Backup', config: 'Configurações do Escritório' };
            $('#page-title').innerText = titles[view] || 'Missy';

            // Renderizar conteúdo
            const content = $('#content-area');
            content.innerHTML = ''; 

            // Adicionar loading fake para transição
            content.innerHTML = `<div class="flex h-full items-center justify-center"><i class="fa-solid fa-circle-notch fa-spin text-brand-500 text-2xl"></i></div>`;

            setTimeout(() => {
                renderView(view, content);
            }, 200);
        }

        // --- RENDERIZADORES DE VIEWS (LÓGICA VISUAL) ---

        function renderView(view, container) {
            container.classList.add('fade-in');
            switch(view) {
                case 'dashboard': renderDashboard(container); break;
                case 'clientes': renderClients(container); break;
                case 'processos': renderProcesses(container); break;
                case 'documentos': renderDocuments(container); break;
                case 'agenda': renderAgenda(container); break;
                case 'finance': renderFinance(container); break;
                case 'tarefas': renderTasks(container); break;
                case 'colaboradores': renderColleagues(container); break;
                case 'intimações': renderIntimations(container); break;
                case 'backup': renderBackup(container); break;
                case 'config': renderSettings(container); break;
            }
        }

        // --- LÓGICA DE CADA MÓDULO ---

        const createClient = () => {
            return {
                id: Date.now().toString(),
                name: '',
                email: '',
                telefone: '',
                crm: ''
            };
        };

        // 1. CLIENTES
        function renderClients(container) {
            container.innerHTML = `
                <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    <!-- Formulário Filtro/Novo -->
                    <div class="lg:col-span-1 space-y-6">
                        <div class="bg-dark-card p-6 rounded-xl border border-dark-border h-full">
                            <h3 class="text-lg font-semibold text-white mb-4 border-b border-dark-border pb-2">Gerenciar Clientes</h3>

                            <form id="client-form" class="space-y-4" onsubmit="event.preventDefault(); saveClient();">
                                <input type="hidden" id="c-id">
                                <div>
                                    <label class="block text-xs font-medium text-slate-400 mb-1">Nome Completo</label>
                                    <input type="text" id="c-name" class="w-full bg-dark-bg border border-dark-border rounded px-3 py-2 text-white focus:outline-none focus:border-brand-500 transition placeholder-slate-500" placeholder="Ex: João da Silva" required>
                                </div>
                                <div class="grid grid-cols-2 gap-4">
                                    <div>
                                        <label class="block text-xs font-medium text-slate-400 mb-1">Email</label>
                                        <input type="email" id="c-email" class="w-full bg-dark-bg border border-dark-border rounded px-3 py-2 text-white focus:outline-none focus:border-brand-500 transition" placeholder="@email.com">
                                    </div>
                                    <div>
                                        <label class="block text-xs font-medium text-slate-400 mb-1">Telefone</label>
                                        <input type="tel" id="c-phone" class="w-full bg-dark-bg border border-dark-border rounded px-3 py-2 text-white focus:outline-none focus:border-brand-500 transition" placeholder="(XX) 9XXXX">
                                    </div>
                                </div>
                                <div>
                                    <label class="block text-xs font-medium text-slate-400 mb-1">OAB/CRM</label>
                                    <input type="text" id="c-crm" class="w-full bg-dark-bg border border-dark-border rounded px-3 py-2 text-white focus:outline-none focus:border-brand-500 transition" placeholder="Número">
                                </div>
                                <div class="pt-2 flex gap-2">
                                    <button type="submit" class="flex-1 bg-brand-600 hover:bg-brand-700 text-white py-2 rounded font-medium transition">Salvar</button>
                                    <button type="button" onclick="resetClientForm()" class="px-4 py-2 border border-dark-border text-slate-400 rounded hover:bg-dark-bg transition">Limpar</button>
                                </div>
                            </form>
                        </div>
                    </div>

                    <!-- Tabela -->
                    <div class="lg:col-span-2 bg-dark-card rounded-xl border border-dark-border overflow-hidden flex flex-col">
                        <div class="p-4 border-b border-dark-border flex justify-between items-center bg-dark-bg/50">
                            <h3 class="font-semibold text-white">Base de Clientes (${appState.clients.length})</h3>
                            <button onclick="openAddClientModal()" class="text-brand-500 hover:text-brand-400"><i class="fa-solid fa-plus mr-1"></i> Novo Cliente</button>
                        </div>
                        <div class="overflow-x-auto flex-1">
                            <table class="w-full text-left text-sm text-slate-400">
                                <thead class="bg-dark-card text-slate-200 uppercase text-xs font-semibold">
                                    <tr>
                                        <th class="px-4 py-3">Nome</th>
                                        <th class="px-4 py-3">Contato</th>
                                        <th class="px-4 py-3">CRM</th>
                                        <th class="px-4 py-3 text-right">Ações</th>
                                    </tr>
                                </thead>
                                <tbody id="clients-table-body" class="divide-y divide-dark-border">
                                    <!-- JS Fill -->
                                </tbody>
                            </table>
                            <div id="empty-client-msg" class="p-8 text-center text-slate-500 hidden">Nenhum cliente cadastrado.</div>
                        </div>
                    </div>
                </div>
            `;

            renderClientsTable(container.getElementById('clients-table-body'));
        }

        function renderClientsTable(tbody) {
            tbody.innerHTML = appState.clients.map(client => `
                <tr class="hover:bg-white/5 transition group">
                    <td class="px-4 py-3 font-medium text-white flex items-center gap-3">
                        <div class="w-8 h-8 rounded-full bg-gradient-to-br from-brand-500 to-brand-700 flex items-center justify-center text-xs text-white font-bold">
                            ${client.name.charAt(0)}
                        </div>
                        ${client.name}
                    </td>
                    <td class="px-4 py-3">
                        ${client.email || '-'}<br/>
                        <span class="text-xs text-slate-500">${client.telefone || '-'}</span>
                    </td>
                    <td class="px-4 py-3 text-brand-500/80">
                        ${client.crm || '-'}
                    </td>
                    <td class="px-4 py-3 text-right">
                        <button onclick="editClient('${client.id}')" class="text-blue-400 hover:text-blue-300 mx-1"><i class="fa-solid fa-pen-to-square"></i></button>
                        <button onclick="deleteClient('${client.id}')" class="text-red-400 hover:text-red-300 mx-1"><i class="fa-solid fa-trash"></i></button>
                    </td>
                </tr>
            `).join('');
        }

        // 2. PROCESSOS
        function renderProcesses(container) {
            container.innerHTML = `
                <div class="space-y-6">
                    <div class="flex justify-between items-end">
                        <div>
                            <h3 class="text-xl font-semibold text-white">Suíte Processual</h3>
                            <p class="text-sm text-slate-500">Visualize e gerencie seus casos jurídicos.</p>
                        </div>
                        <button onclick="openAddProcessModal()" class="bg-brand-600 hover:bg-brand-700 text-white px-4 py-2 rounded shadow hover:shadow-lg transition flex items-center gap-2">
                            <i class="fa-solid fa-plus"></i> Novo Processo
                        </button>
                    </div>

                    <div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                        ${appState.processes.length === 0 ? 
                            `<div class="col-span-full p-8 border border-dashed border-slate-700 rounded-xl text-center text-slate-500">Sem processos ativos.</div>` : 
                            appState.processes.map(proc => `
                                <div class="bg-dark-card border border-dark-border rounded-xl p-5 hover:border-brand-500/50 transition group relative overflow-hidden">
                                    ${proc.stage === 'Pendente' ? '<div class="absolute top-0 left-0 w-1 h-full bg-yellow-500"></div>' : ''}
                                    ${proc.stage === 'Ativo' ? '<div class="absolute top-0 left-0 w-1 h-full bg-brand-500"></div>' : ''}
                                    ${proc.stage === 'Encerrado' ? '<div class="absolute top-0 left-0 w-1 h-full bg-green-500"></div>' : ''}

                                    <div class="flex justify-between items-start mb-4 pl-2">
                                        <span class="px-2 py-0.5 rounded text-xs font-semibold ${proc.stage === 'Pendente' ? 'bg-yellow-500/10 text-yellow-500' : proc.stage === 'Ativo' ? 'bg-brand-500/10 text-brand-500' : 'bg-green-500/10 text-green-500'}">
                                            ${proc.stage}
                                        </span>
                                        <div class="flex gap-2 opacity-0 group-hover:opacity-100 transition absolute top-2 right-2">
                                            <button onclick="editProcess('${proc.id}')" class="p-1.5 hover:bg-white/10 rounded text-slate-300"><i class="fa-solid fa-pen"></i></button>
                                            <button onclick="deleteProcess('${proc.id}')" class="p-1.5 hover:bg-red-500/20 rounded text-red-400"><i class="fa-solid fa-trash"></i></button>
                                        </div>
                                    </div>

                                    <h4 class="text-lg font-medium text-white leading-tight pl-2 mb-1">${proc.title}</h4>
                                    <div class="pl-2 space-y-1">
                                        <div class="flex items-center text-sm text-slate-400">
                                            <i class="fa-solid fa-user-tie w-6 text-slate-500"></i> <span>${getFormattedDate(proc.created_at)}</span>
                                        </div>
                                        <div class="flex items-center text-sm text-slate-400">
                                            <i class="fa-solid fa-link w-6 text-slate-500"></i> <span class="text-brand-500">#CLI_${proc.clientId.split('-')[1]}</span>
                                        </div>
                                    </div>
                                    <div class="mt-4 pt-4 border-t border-dark-border flex justify-between items-center text-sm">
                                        <span class="text-slate-500">Valores: R$ ${(proc.value || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                                        <span class="text-xs bg-dark-bg px-2 py-1 rounded text-slate-400">${proc.desc || 'Sem descrição específica'}</span>
                                    </div>
                                </div>
                            `).join('')
                        }
                    </div>
                </div>
            `;
        }

        // 3. DOCUMENTOS (Simplificado)
        function renderDocuments(container) {
            container.innerHTML = `
                <div class="bg-dark-card rounded-xl border border-dark-border overflow-hidden">
                     <div class="p-4 border-b border-dark-border flex justify-between items-center">
                        <h3 class="font-semibold text-white">Documentação Indexada</h3>
                        <button onclick="documentUpload()" class="text-brand-500"><i class="fa-solid fa-cloud-arrow-up"></i> Upload</button>
                     </div>
                     <div class="overflow-x-auto">
                         <table class="w-full text-left text-sm text-slate-400">
                             <thead class="bg-dark-card text-xs uppercase text-slate-500">
                                 <tr><th class="px-4 py-3">Arquivo</th><th class="px-4 py-3">Tipo</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Ações</th></tr>
                             </thead>
                             <tbody class="divide-y divide-dark-border">
                                 ${appState.documents.length === 0 ? '<tr><td colspan="4" class="p-8 text-center">Sem arquivos.</td></tr>' : ''}
