                                     <tr class="hover:bg-white/5 group">
                                         <td class="px-4 py-3 font-medium text-white flex items-center gap-2">
                                             <div class="w-8 h-8 bg-slate-700 rounded flex items-center justify-center text-slate-400"><i class="fa-solid fa-file-pdf"></i></div>
                                             <span class="truncate max-w-[150px]">${doc.path}</span>
                                         </td>
                                         <td class="px-4 py-3">${doc.type}</td>
                                         <td class="px-4 py-3">
                                             ${doc.status === 'Pendente' ? '<span class="bg-yellow-500/10 text-yellow-500 px-2 py-0.5 rounded text-xs">Pendente</span>' : '<span class="bg-green-500/10 text-green-500 px-2 py-0.5 rounded text-xs">Processe</span>'}
                                         </td>
                                         <td class="px-4 py-3 text-right">
                                             <button onclick="viewDoc('${doc.path}')" class="text-blue-400 hover:text-white"><i class="fa-solid fa-eye"></i></button>
                                         </td>
                                     </tr>
                                 `).join('')}
                             </tbody>
                         </table>
                     </div>
                </div>
            `;
        }

        // 4. AGENDA
        function renderAgenda(container) {
