                            ${['15', '20', '25'].map(day => {
                                const events = appState.agenda.filter(e => new Date(e.date).getDate() == day && !e.completed); // Fake events logic
                                return `
                                    <div class="pl-4 border-l-2 border-slate-700 hover:border-brand-500 transition group relative py-1">
                                        <span class="text-slate-500 text-sm absolute -left-8 select-none">${day}</span>
                                        <div class="group-hover:translate-x-1 transition-transform inline-block">
