                                '<span class="text-xs bg-red-500/20 text-red-400 px-2 py-1 rounded animate-pulse">ATENÇÃO: URGENTE</span>' : ''}
                        </div>

                        <div class="space-y-3" id="agenda-list-container">
                            ${appState.agenda.map(ev => `
                                <div class="bg-dark-card p-4 rounded-lg border border-dark-border flex items-start gap-4">
